using System;
using System.IO;
using System.Linq;
using PhotoLib.Tiff;
using Xunit;
using Xunit.Abstractions;

namespace PhotoTests.Canon1D3;

public class C1D3Ifd0
{
    private const string FileName = @"P:\2024\2024-08-31\2B0I7592.CR2";
    private readonly ITestOutputHelper _testOutputHelper;

    public C1D3Ifd0(ITestOutputHelper testOutputHelper)
    {
        _testOutputHelper = testOutputHelper;
        Assert.True(File.Exists(FileName), $"Image file {FileName} doesn't exists!");
    }

    [Fact]
    public void DumpImageFileDirectory()
    {
        using var fileStream = File.Open(FileName, FileMode.Open, FileAccess.Read, FileShare.Read);
        using var binaryReader = new BinaryReader(fileStream);
        var rawImage = new RawImage(binaryReader);
        var imageFileDirectory = rawImage.Directories.First();

        var directory = imageFileDirectory.DumpDirectory(binaryReader);
        _testOutputHelper.WriteLine(directory);
    }

    // == Tiff Directory[0x00000010]:
    // ImageWidth       IFD0:0x0100  0)  UShort 16-bit: 1936
    // ImageLength      IFD0:0x0101  1)  UShort 16-bit: 1288
    // BitsPerSample    IFD0:0x0102  2)  UShort 16-bit: [0x000000CA] (3): 8, 8, 8, 
    // Compression      IFD0:0x0103  3)  UShort 16-bit: 6 = JPEG (old-style)
    // Make             IFD0:0x010F  4)  Ascii 8-bit, null terminated: [0x000000D0] (6): "Canon"
    // Model            IFD0:0x0110  5)  Ascii 8-bit, null terminated: [0x000000D6] (22): "Canon EOS-1D Mark III"
    // StripOffsets     IFD0:0x0111  6)  ULong 32-bit: 50924
    // Orientation      IFD0:0x0112  7)  UShort 16-bit: 1
    // StripByteCounts  IFD0:0x0117  8)  ULong 32-bit: 787019
    // XResolution      IFD0:0x011A  9)  URational 2x32-bit: [0x000000F6] (1): 72/1 = 72
    // YResolution      IFD0:0x011B 10)  URational 2x32-bit: [0x000000FE] (1): 72/1 = 72
    // ResolutionUnit   IFD0:0x0128 11)  UShort 16-bit: 2 = inches
    // DateTime         IFD0:0x0132 12)  Ascii 8-bit, null terminated: [0x00000106] (20): "2024:08:31 09:04:04"
    // Exif IFD Pointer IFD0:0x8769 13)  Image File Directory: [0x0000011A] (1): 
    // GPS IFD Pointer  IFD0:0x8825 14)  Image File Directory: [0x000085FE] (1):       

    [Fact]
    public void TagsInDirectory()
    {
        using var fileStream = File.Open(FileName, FileMode.Open, FileAccess.Read, FileShare.Read);
        using var binaryReader = new BinaryReader(fileStream);
        var rawImage = new RawImage(binaryReader);
        var imageFileDirectory = rawImage.Directories.First();

        Assert.Equal(
            new ushort[] 
            { 
                0x0100, 0x0101, 0x0102, 0x0103, 0x010F, 0x0110, 0x0111, 0x0112, 0x0117, 0x011A, 0x011B, 0x0128, 
                0x0132, 0x8769, 0x8825
            },
            imageFileDirectory.Entries.Select(e => e.TagId).ToArray());
    }

    [Fact]
    public void ImageWidth()
    {
        using var fileStream = File.Open(FileName, FileMode.Open, FileAccess.Read, FileShare.Read);
        using var binaryReader = new BinaryReader(fileStream);
        var rawImage = new RawImage(binaryReader);

        // 0x0100 UShort 16-bit: 1936
        var imageFileDirectory = rawImage.Directories.First();
        var imageFileEntry = imageFileDirectory[0x0100];
        Assert.Equal(ImageFileEntry.TagTypes.UShort, imageFileEntry.TagType);
        Assert.Equal(1936u, imageFileEntry.ValuePointer);
        Assert.Equal(1u, imageFileEntry.NumberOfValue);
    }

    [Fact]
    public void ImageLength()
    {
        using var fileStream = File.Open(FileName, FileMode.Open, FileAccess.Read, FileShare.Read);
        using var binaryReader = new BinaryReader(fileStream);
        var rawImage = new RawImage(binaryReader);

        // 0x0101 UShort 16-bit: 1288
        var imageFileDirectory = rawImage.Directories.First();
        var imageFileEntry = imageFileDirectory[0x0101];
        Assert.Equal(ImageFileEntry.TagTypes.UShort, imageFileEntry.TagType);
        Assert.Equal(1288u, imageFileEntry.ValuePointer);
        Assert.Equal(1u, imageFileEntry.NumberOfValue);
    }

    [Fact]
    public void BitsPerSample()
    {
        using var fileStream = File.Open(FileName, FileMode.Open, FileAccess.Read, FileShare.Read);
        using var binaryReader = new BinaryReader(fileStream);
        var rawImage = new RawImage(binaryReader);

        // 0x0102 UShort 16-bit: [0x000000CA] (3): 8, 8, 8, 
        var imageFileDirectory = rawImage.Directories.First();
        var imageFileEntry = imageFileDirectory[0x0102];
        Assert.Equal(ImageFileEntry.TagTypes.UShort, imageFileEntry.TagType);
        Assert.Equal(202u, imageFileEntry.ValuePointer);
        Assert.Equal(3u, imageFileEntry.NumberOfValue);

        Assert.Equal(new[] {(ushort) 8, (ushort) 8, (ushort) 8},
            RawImage.ReadUInts16(binaryReader, imageFileEntry));
    }

    [Fact]
    public void Compression()
    {
        using var fileStream = File.Open(FileName, FileMode.Open, FileAccess.Read, FileShare.Read);
        using var binaryReader = new BinaryReader(fileStream);
        var rawImage = new RawImage(binaryReader);

        // 0x0103 UShort 16-bit: 6
        var imageFileDirectory = rawImage.Directories.First();
        var imageFileEntry = imageFileDirectory[0x0103];
        Assert.Equal(ImageFileEntry.TagTypes.UShort, imageFileEntry.TagType);
        Assert.Equal(6u, imageFileEntry.ValuePointer);
        Assert.Equal(1u, imageFileEntry.NumberOfValue);
    }

    [Fact]
    public void Maker()
    {
        using var fileStream = File.Open(FileName, FileMode.Open, FileAccess.Read, FileShare.Read);
        using var binaryReader = new BinaryReader(fileStream);
        var rawImage = new RawImage(binaryReader);

        // 0x010F Ascii 8-bit: [0x000000D0] (6): Canon
        var imageFileDirectory = rawImage.Directories.First();
        var imageFileEntry = imageFileDirectory[0x010F];
        Assert.Equal(ImageFileEntry.TagTypes.Ascii, imageFileEntry.TagType);
        Assert.Equal(0x000000D0u, imageFileEntry.ValuePointer);
        Assert.Equal(6u, imageFileEntry.NumberOfValue);

        Assert.Equal("Canon", RawImage.ReadChars(binaryReader, imageFileEntry));
    }

    [Fact]
    public void Model()
    {
        using var fileStream = File.Open(FileName, FileMode.Open, FileAccess.Read, FileShare.Read);
        using var binaryReader = new BinaryReader(fileStream);
        var rawImage = new RawImage(binaryReader);

        // 0x0110 Ascii 8-bit: [0x000000D6] (22): "Canon EOS-1D Mark III"
        var imageFileDirectory = rawImage.Directories.First();
        var imageFileEntry = imageFileDirectory[0x0110];
        Assert.Equal(ImageFileEntry.TagTypes.Ascii, imageFileEntry.TagType);
        Assert.Equal(0x000000D6u, imageFileEntry.ValuePointer);
        Assert.Equal(22u, imageFileEntry.NumberOfValue);

        Assert.Equal("Canon EOS-1D Mark III", RawImage.ReadChars(binaryReader, imageFileEntry));
    }

    // stripOffset 6)  0x0111 ULong 32-bit: 50924
    // orientation 7)  0x0112 UShort 16-bit: 1
    // stripByteCounts 8)  0x0117 ULong 32-bit: 787019
    // xResolution 9)  0x011A Rational 2x32-bit: [0x000000F6] (2): 72/1 = 72
    // yResolution 10)  0x011B Rational 2x32-bit: [0x000000FE] (2): 72/1 = 72
    // resolutionUnit 11)  0x0128 UShort 16-bit: 2, pixels per inch
    // dateTime 12)  0x0132 Ascii 8-bit: [0x00000106] (20): 2024:08:31 09:04:04
    // Exif IFD Pointer 13) 0x8769 Image File Directory: [0x0000011A] (1): 
    // GPS IFD Pointer  14) 0x8825 Image File Directory: [0x000085FE] (1):       

    [Fact]
    public void ExifTags()
    {
        using var fileStream = File.Open(FileName, FileMode.Open, FileAccess.Read, FileShare.Read);
        using var binaryReader = new BinaryReader(fileStream);
        var rawImage = new RawImage(binaryReader);
        var imageFileDirectory = rawImage.Directories.First();

        var imageFileEntry = imageFileDirectory[0x8769];
        Assert.Equal(ImageFileEntry.TagTypes.ULong, imageFileEntry.TagType);
        Assert.Equal(0x0000011Au, imageFileEntry.ValuePointer);
        Assert.Equal(1u, imageFileEntry.NumberOfValue);

        binaryReader.BaseStream.Seek(imageFileEntry.ValuePointer, SeekOrigin.Begin);
        var tags = new ImageFileDirectory(binaryReader);
        var directory = tags.DumpDirectory(binaryReader, ":0x8769");
        _testOutputHelper.WriteLine(directory);
    }

